{
  "understood": "Тебе нужен новый анимационный сериал с ярким героем, экшеном и лёгким юмором: не аниме, без натуралистичной жестокости, до 30 минут.",
  "picks": [
    {
      "id": "tt0318233",
      "title": "",
      "year": 0,
      "reason": "Дженни совмещает спасение мира с подростковой жизнью — близко к Человеку-пауку по характеру, приключениям и юмору.",
      "caveat": "Школьные заботы занимают заметную часть историй.",
      "likelySeen": false,
      "constraintChecks": [
        {
          "key": "fact:content.violence:5c4100ab0c874ef0",
          "status": "compatible",
          "reason": "Стилизованные бои с роботами и чудовищами, без натуралистичной жестокости."
        },
        {
          "key": "fact:format.anime:2c50c8998ed898d3",
          "status": "compatible",
          "reason": "Американский анимационный сериал, не аниме."
        },
        {
          "key": "fact:viewing.new_experience:69b0b0a685bfff27",
          "status": "unknown",
          "reason": "Не пересказ приключений Бэтмена или Человека-паука; смотрел ли ты этот сериал, неизвестно."
        },
        {
          "key": "session:minutes:34040f1fb29a7069",
          "status": "compatible",
          "reason": "Эпизоды около 23 минут."
        }
      ]
    },
    {
      "id": "tt0361201",
      "title": "",
      "year": 0,
      "reason": "Самоуверенный Куп спасает Землю на переделанном роботе: герой с характером, стремительные драки и лёгкий юмор.",
      "caveat": "Много пародий на игры и фильмы; герой скорее разгильдяй, чем образец ответственности.",
      "likelySeen": false,
      "constraintChecks": [
        {
          "key": "fact:content.violence:5c4100ab0c874ef0",
          "status": "compatible",
          "reason": "Масштабные, но условные роботизированные битвы без натуралистичной жестокости."
        },
        {
          "key": "fact:format.anime:2c50c8998ed898d3",
          "status": "compatible",
          "reason": "Американская анимация, пародирующая в том числе меха-аниме, но сама не аниме."
        },
        {
          "key": "fact:viewing.new_experience:69b0b0a685bfff27",
          "status": "unknown",
          "reason": "Самостоятельная история с другими героями; сведений о твоём знакомстве с ней нет."
        },
        {
          "key": "session:minutes:34040f1fb29a7069",
          "status": "compatible",
          "reason": "Обычный эпизод длится около 22 минут, укладываясь в предел 30 минут."
        }
      ]
    },
    {
      "id": "tt0111970",
      "title": "",
      "year": 0,
      "reason": "Фриказоид — супергерой с буйным характером: погони и злодеи сохраняют нужный экшен, а юмор превращает его в пародию.",
      "caveat": "Абсурд и разговоры со зрителем часто важнее связного приключения.",
      "likelySeen": false,
      "constraintChecks": [
        {
          "key": "fact:content.violence:5c4100ab0c874ef0",
          "status": "compatible",
          "reason": "Комические потасовки и мультяшные удары без натуралистичной жестокости."
        },
        {
          "key": "fact:format.anime:2c50c8998ed898d3",
          "status": "compatible",
          "reason": "Американский рисованный сериал, не аниме."
        },
        {
          "key": "fact:viewing.new_experience:69b0b0a685bfff27",
          "status": "unknown",
          "reason": "Другой супергерой и самостоятельный сериал; смотрел ли ты его раньше, неизвестно."
        },
        {
          "key": "session:minutes:34040f1fb29a7069",
          "status": "compatible",
          "reason": "Эпизоды около 22 минут без рекламного блока, не больше 30 минут."
        }
      ]
    }
  ]
}
